            let p = &p;
            let calls = &calls;
            scope.spawn(move || {
                let request = MutationRequest {
                    request_id: Uuid::new_v4(),
                    runtime_id: p.lease.runtime_id,
                    actor: Actor {
                        identity: "component worker".into(),
                        roles: BTreeSet::new(),
